        const A = DD.art; A.R(X, Y, 16, 6, '#4a82c0'); A.R(X, Y + 1, 16, 4, '#9ad0ff'); A.R(X, Y, 16, 1, '#ffffff'); A.R(X, Y + 5, 16, 1, '#2a4a78'); A.R(X, Y + 3, 16, 1, '#b8e0ff'); A.R(X + 15, Y, 1, 6, '#2a4a78'); A.R(X + 2, Y + 6, 2, 3, '#2a4a78'); A.R(X + 12, Y + 6, 2, 3, '#2a4a78'); A.R(X + 2, Y + 6, 1, 3, '#4a82c0'); A.R(X + 12, Y + 6, 1, 3, '#4a82c0');
