        if (top) { A.R(X, Y, 16, 3, '#ffffff'); A.R(X, Y + 3, 16, 1, '#8ab0c8'); } A.R(X + 1, Y + 5, 14, 6, '#b0d8ec'); A.R(X + 1, Y + 5, 14, 1, '#6a9ab8'); A.R(X + 1, Y + 10, 14, 1, '#ffffff');
        A.R(X + 3, Y + 6, 9, 1, '#a8c8dc'); if (h < 5) { A.R(X + 4, Y + 7, 3, 3, '#3a8ad8'); A.R(X + 4, Y + 7, 3, 1, '#8ac0f0'); } if (h > 9) A.R(X + 9, Y + 7, 3, 3, '#e8a8c0');
