        if (top) { A.R(X, Y, 16, 4, '#05080e'); const o = ((DD.G.frame >> 1) + tx * 3) % 8; A.R(X, Y + 1, 16, 2, '#101a24'); for (let i = -8; i < 16; i += 8) { const x0 = Math.max(0, X + i + o - X); if (x0 < 14) A.R(X + x0, Y + 1, 2, 2, '#3a4a5a'); } A.R(X, Y, 16, 1, '#9ab0c4'); }
